<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte de bancos</title><?php include_once 'linker.php'; ?>
<style>.bank-report{padding:20px;color:#173e52}.bank-hero{background:linear-gradient(110deg,#12384d,#0b656c);color:white;padding:10px 22px;border-radius:16px;margin-bottom:16px}.bank-hero small{display:block;font-size:10px;line-height:12px;margin:0}.bank-hero h2{font-size:24px;line-height:29px;margin:3px 0!important}.bank-hero p{font-size:13px;line-height:17px;margin:0!important}.bank-panel{background:white;border:1px solid #cfe2ec;border-radius:16px;padding:20px;margin:15px 0}.bank-filters{display:flex;gap:16px;align-items:end;flex-wrap:wrap}.bank-filters label{flex:1;min-width:180px}.bank-report table{width:100%;border-collapse:collapse}.bank-report th{background:#153f54;color:white}.bank-report td,.bank-report th{padding:11px;border-bottom:1px solid #e1ebf1;vertical-align:top}.bank-report tr:nth-child(even){background:#f2f8fb}.bank-num{text-align:right;white-space:nowrap}.bank-scroll{overflow:auto}.bank-note{padding:14px;background:#eaf7fa;border-radius:10px}.bank-void{color:#b26666}.bank-report h3{font-size:22px}#bank-error{color:#b3223e;margin-top:12px}#bank-loading{margin:15px}button:disabled{opacity:.5}.bank-balances{display:flex;gap:16px;flex-wrap:wrap;margin:18px 0}.bank-balance{flex:1;min-width:260px;padding:22px;border-radius:16px;background:white;border:1px solid #cfe2ec;border-top:5px solid #0b8c8d}.bank-balance strong{display:block;font-size:30px;margin:10px 0;color:#08776e}.bank-balance.negative strong{color:#b22941}.bank-balance small{display:block;color:#547184;margin:8px 0}.bank-report tfoot td{background:#e8f3f7;font-weight:bold;border-top:2px solid #153f54}.bank-user{font-weight:bold;color:#086d80}</style></head><body><?php include 'header.php'; ?>
<main class="bank-report"><section class="bank-hero"><small>CAJA Y BANCO</small><h2>Reporte de movimientos bancarios</h2><p>Consolidado por cuenta, depósitos, salidas y pagos al personal.</p></section>
<form id="bank-form" class="bank-panel bank-filters"><label>Desde<input required type="date" class="form-control" id="bank-from" value="<?=date('Y-m-01')?>"></label><label>Hasta<input required type="date" class="form-control" id="bank-to" value="<?=date('Y-m-d')?>"></label><label>Cuenta<select id="bank-account" class="form-control"><option value="0">Todas las cuentas bancarias</option></select></label><button class="btn btn-info" type="submit">Consultar</button><button class="btn btn-success" type="button" id="bank-pdf">Generar PDF</button><a class="btn btn-outline-info" href="SaldosBancos.php">Configurar saldos iniciales</a></form>
<p class="bank-note">Caja Principal está excluida. Los pagos al personal son parte de las salidas y no se suman dos veces. Los saldos corresponden al saldo inicial más ingresos menos salidas. Al configurar un inicio de control, los movimientos anteriores a esa fecha quedan fuera del cálculo de esa cuenta.</p><div id="bank-error" role="alert"></div><div id="bank-loading" hidden>Cargando movimientos...</div><section id="bank-results"></section></main>
<script>
(function(){
 const $=id=>document.getElementById(id),esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});
 const query=()=>{if(!$('bank-form').reportValidity())return null;if($('bank-from').value>$('bank-to').value){$('bank-error').textContent='La fecha inicial debe ser menor o igual a la fecha final.';return null;}return new URLSearchParams({desde:$('bank-from').value,hasta:$('bank-to').value,cuenta:$('bank-account').value}).toString();};
 let loading=false;
 async function load(){const p=query();if(!p||loading)return;loading=true;$('bank-loading').hidden=false;$('bank-error').textContent='';try{const response=await fetch('/api/index.php/bancos/reporte?'+p,{credentials:'same-origin'}),d=await response.json();if(!response.ok)throw new Error(d.error||'Error al consultar');
 if($('bank-account').options.length===1&&$('bank-account').value==='0')d.Cuentas.forEach(g=>{const o=document.createElement('option');o.value=g.IdCuenta;o.textContent=g.Cuenta;$('bank-account').appendChild(o);});
 let html='<div class="bank-balances">'+d.Cuentas.map(g=>'<article class="bank-balance '+(Number(g.Saldo)<0?'negative':'')+'"><h3>'+esc(g.Cuenta)+'</h3><small>'+(g.ControlActivo?'Control desde '+esc(g.FechaControl)+' · Saldo inicial S/ '+money(g.BaseControl):'Sin saldo inicial configurado para este rango')+'</small><small>Saldo registrado al '+esc(d.Hasta)+'</small><strong>S/ '+money(g.Saldo)+'</strong><div>Inicial '+money(g.Inicial)+' + ingresos '+money(g.Ingresos)+' − salidas '+money(g.Salidas)+'</div><small>Registrado por: '+esc(g.Usuarios.join(', ')||'Sin movimientos en el rango')+'</small>'+(Number(g.Saldo)<0?'<small>Saldo negativo según el historial registrado. Verifica el saldo inicial y los depósitos.</small>':'')+'</article>').join('')+'</div>';
 html+='<section class="bank-panel"><h3>Consolidado por cuenta</h3><div class="bank-scroll"><table><thead><tr><th>Cuenta</th><th>Inicial S/</th><th>Ingresos S/</th><th>Salidas S/</th><th>Personal S/ (incluido)</th><th>Saldo al cierre S/</th></tr></thead><tbody>';
 d.Cuentas.forEach(g=>html+='<tr><td><b>'+esc(g.Cuenta)+'</b></td>'+['Inicial','Ingresos','Salidas','Personal','Saldo'].map(k=>'<td class="bank-num">'+money(g[k])+'</td>').join('')+'</tr>');html+='<tr><td><b>TOTAL BANCOS</b></td>'+['Inicial','Ingresos','Salidas','Personal','Saldo'].map(k=>'<td class="bank-num"><b>'+money(d.Cuentas.reduce((sum,g)=>sum+Number(g[k]),0))+'</b></td>').join('')+'</tr>';html+='</tbody></table></div></section>';
 d.Cuentas.forEach(g=>{html+='<section class="bank-panel"><h3>'+esc(g.Cuenta)+'</h3><div class="bank-scroll"><table><thead><tr><th>Fecha / ID</th><th>Operación</th><th>Personal / proveedor / cliente</th><th>Detalle / referencia</th><th>Registrado por</th><th>Ingreso S/</th><th>Salida S/</th><th>Saldo S/</th></tr></thead><tbody>';g.Movimientos.forEach(m=>html+='<tr class="'+(m.Anulado?'bank-void':'')+'"><td>'+esc(m.FechaDoc)+'<br>#'+esc(m.IdCajaBanco)+'</td><td>'+esc(m.Operacion)+(m.Anulado?'<br>ANULADO':'')+'</td><td>'+esc(m.Beneficiario)+'</td><td>'+esc(m.Concepto)+'<br>'+esc(m.Referencia)+'</td><td class="bank-user">'+esc(m.RegistradoPor)+'</td>'+['Ingreso','Salida','Saldo'].map(k=>'<td class="bank-num">'+money(m[k])+'</td>').join('')+'</tr>');if(!g.Movimientos.length)html+='<tr><td colspan="8">Sin movimientos en el rango seleccionado.</td></tr>';html+='</tbody><tfoot><tr><td colspan="5">SUMATORIA '+esc(g.Cuenta)+'</td><td class="bank-num">'+money(g.Ingresos)+'</td><td class="bank-num">'+money(g.Salidas)+'</td><td class="bank-num">'+money(g.Saldo)+'</td></tr></tfoot></table></div></section>';});$('bank-results').innerHTML=html;
 }catch(e){$('bank-results').textContent='';$('bank-error').textContent=e.message;}finally{loading=false;$('bank-loading').hidden=true;}}
 $('bank-form').addEventListener('submit',e=>{e.preventDefault();load();});$('bank-pdf').addEventListener('click',()=>{const p=query();if(p)window.open('/api/index.php/bancos/reporte/pdf?'+p,'_blank');});load();
})();
</script></body></html>
